import{_ as o,o as a,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"第 21 章 岗位路线图：不同岗位如何把我用深（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第21章 岗位路线图：不同岗位如何把我用深（易懂版）.md","filePath":"easy/第21章 岗位路线图：不同岗位如何把我用深（易懂版）.md"}'),n={name:"easy/第21章 岗位路线图：不同岗位如何把我用深（易懂版）.md"};function s(d,t,l,i,u,h){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-21-章-岗位路线图-不同岗位如何把我用深-易懂版" tabindex="-1">第 21 章 岗位路线图：不同岗位如何把我用深（易懂版） <a class="header-anchor" href="#第-21-章-岗位路线图-不同岗位如何把我用深-易懂版" aria-label="Permalink to &quot;第 21 章 岗位路线图：不同岗位如何把我用深（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 21 章 岗位路线图：不同岗位如何把我用深（完整版）](../../bluebook/第四篇 岗位与行业落地/第 21 章 岗位路线图：不同岗位如何把我用深.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>AI 不是&quot;谁都能用&quot;，而是&quot;每个岗位都有自己的用法&quot;——找到你岗位的用力点。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>锤子、螺丝刀、电钻都是工具，但木匠用锤子、电工用螺丝刀——<strong>工具好不好用，取决于你用在哪</strong>。</p><p>AI 也一样：<strong>产品经理、程序员、运营、HR……每个岗位的&quot;高价值用法&quot;不一样。</strong></p><h2 id="六个岗位怎么用-ai-速查" tabindex="-1">六个岗位怎么用 AI（速查） <a class="header-anchor" href="#六个岗位怎么用-ai-速查" aria-label="Permalink to &quot;六个岗位怎么用 AI（速查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>岗位</th><th>最该用 AI 干的活</th><th>一句话心法</th></tr></thead><tbody><tr><td><strong>产品经理</strong></td><td>需求整理、竞品分析、PRD 草稿</td><td>把&quot;调研和文档&quot;交给 AI，你专注判断</td></tr><tr><td><strong>程序员</strong></td><td>脚手架代码、调试、代码 review 初筛</td><td>让 AI 提速，别让它背锅</td></tr><tr><td><strong>运营</strong></td><td>内容排期、数据周报、活动文案</td><td>用 AI 量产初稿，你来把关调性</td></tr><tr><td><strong>设计师</strong></td><td>文案配图、规范整理、方案说明</td><td>AI 做&quot;苦活&quot;，创意还是你的</td></tr><tr><td><strong>市场</strong></td><td>素材收集、投放数据解读、方案框架</td><td>让 AI 先消化数据，你定策略</td></tr><tr><td><strong>管理者</strong></td><td>会议纪要、周报汇总、进度追踪</td><td>把 AI 当&quot;秘书+分析师&quot;</td></tr></tbody></table><h2 id="三个阶段-你现在在第几级" tabindex="-1">三个阶段（你现在在第几级？） <a class="header-anchor" href="#三个阶段-你现在在第几级" aria-label="Permalink to &quot;三个阶段（你现在在第几级？）&quot;">​</a></h2><ol><li><strong>会用</strong>：能说清需求，拿到可用结果（第 1-8 章）；</li><li><strong>好用</strong>：会挑场景、会纠错、把常用流程固化成模板（第 9-16 章）；</li><li><strong>用深</strong>：能带 AI 团队、自建 Skill、让它参与关键决策支撑（第 17-22 章）。</li></ol><p><strong>大多数人停在&quot;会用&quot;——往上走一层，效率翻几倍。</strong></p><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p>你是运营：&quot;帮我建一个&#39;活动复盘&#39;模板：每次活动后，自动整理数据、对比目标、生成 5 条可复用的经验。&quot; 这就是&quot;好用&quot;阶段——<strong>把重复动作模板化</strong>。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 跟风学别人岗位的用法——<strong>先找自己岗位最高频、最耗时的活</strong>；</li><li>❌ 只当&quot;打字员&quot;——<strong>别让 AI 替你思考，让它替你干活</strong>；</li><li>❌ 停留在&quot;会用&quot;——<strong>目标是&quot;好用&quot;和&quot;用深&quot;</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>找到你岗位最高频、最耗时的活，用 AI 干，然后逐步模板化、团队化。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>写出你岗位的<strong>一个高频耗时任务</strong>——这就是你第一个&quot;用深&quot;的切入点。</p><p>👉 [下一章：行业路线图，从通用能力到行业工作流（易懂版）](第22章 行业路线图：从通用能力到行业工作流（易懂版）.md)</p>',21)])])}const g=o(n,[["render",s]]);export{_ as __pageData,g as default};
